/// Decodes one message from the JS channel, checks the per-launch [nonce] the host served in the entry page,
/// calls the handler and returns the reply JSON. Never throws.
Future<String> bridgeDispatch(BridgeHandlers h, String raw, {required String nonce}) async {
  Object? id;
  try {
    final Object? decoded;
    try {
      decoded = jsonDecode(raw);
    } on FormatException {
      throw const BridgeError('E_PARAMS', 'message is not JSON');
    }
    final msg = decodeObject(decoded, 'message');
    id = msg['id'];
    if (nonce.isEmpty || msg['n'] != nonce) throw const BridgeError('E_DENIED', 'bad nonce');
    final p = msg['p'] ?? const <String, Object?>{};
    switch (msg['m']) {
      case 'app.ready':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        await h.appReady();
        return replyOk(id, null);
      case 'app.info':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.appInfo();
        return replyOk(id, r.toJson());
      case 'data.get':
        final r = await h.dataGet(DataGetParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'data.list':
        final r = await h.dataList(DataListParams.fromJson(p, 'p'));
        return replyOk(id, r.map((e) => e.toJson()).toList());
      case 'data.put':
        await h.dataPut(DataPutParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'sync.now':
        final r = await h.syncNow(SyncNowParams.fromJson(p, 'p'));
        return replyOk(id, r.toJson());
      case 'prefs.get':
        final r = await h.prefsGet(PrefsGetParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'prefs.set':
        await h.prefsSet(PrefsSetParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'open.external':
        await h.openExternal(OpenExternalParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'bundle.applyUpdate':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        await h.bundleApplyUpdate();
        return replyOk(id, null);
      case 'secure.get':
        final r = await h.secureGet(SecureGetParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'secure.set':
        await h.secureSet(SecureSetParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'secure.delete':
        await h.secureDelete(SecureDeleteParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'auth.setToken':
        await h.authSetToken(AuthSetTokenParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'auth.hasToken':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.authHasToken();
        return replyOk(id, r);
      case 'auth.account':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.authAccount();
        return replyOk(id, r);
      case 'http.request':
        final r = await h.httpRequest(HttpRequestParams.fromJson(p, 'p'));
        return replyOk(id, r.toJson());
      case 'data.getMany':
        final r = await h.dataGetMany(DataGetManyParams.fromJson(p, 'p'));
        return replyOk(id, r.map((e) => e.toJson()).toList());
      case 'sync.status':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.syncStatus();
        return replyOk(id, r.toJson());
      case 'app.state':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.appState();
        return replyOk(id, r.toJson());
      case 'bundle.status':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.bundleStatus();
        return replyOk(id, r.toJson());
      case 'data.count':
        final r = await h.dataCount(DataCountParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'state.save':
        await h.stateSave(StateSaveParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'state.restore':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.stateRestore();
        return replyOk(id, r);
      case 'link.initial':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.linkInitial();
        return replyOk(id, r?.toJson());
      case 'permissions.check':
        final r = await h.permissionsCheck(PermissionsCheckParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'permissions.request':
        final r = await h.permissionsRequest(PermissionsRequestParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'permissions.openSettings':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.permissionsOpenSettings();
        return replyOk(id, r);
      case 'notify.permission':
        final r = await h.notifyPermission(NotifyPermissionParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'notify.schedule':
        final r = await h.notifySchedule(NotifyScheduleParams.fromJson(p, 'p'));
        return replyOk(id, r.toJson());
      case 'notify.cancel':
        await h.notifyCancel(NotifyCancelParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'notify.pending':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.notifyPending();
        return replyOk(id, r.map((e) => e.toJson()).toList());
      case 'notify.initial':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.notifyInitial();
        return replyOk(id, r);
      case 'notify.channels.set':
        await h.notifyChannelsSet(NotifyChannelsSetParams.fromJson(p, 'p'));
        return replyOk(id, null);
      case 'badge.set':
        final r = await h.badgeSet(BadgeSetParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'badge.clear':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.badgeClear();
        return replyOk(id, r);
      case 'push.token':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.pushToken();
        return replyOk(id, r);
      case 'push.permission':
        final r = await h.pushPermission(PushPermissionParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'push.initial':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        final r = await h.pushInitial();
        return replyOk(id, r?.toJson());
      case 'share.image':
        final r = await h.shareImage(ShareImageParams.fromJson(p, 'p'));
        return replyOk(id, r);
      case 'haptics.tap':
        decodeKeys(decodeObject(p, 'p'), const {}, 'p');
        await h.hapticsTap();
        return replyOk(id, null);
      default:
        throw BridgeError('E_UNKNOWN', 'unknown method ${msg['m']}');
    }
  } on BridgeError catch (e) {
    return replyError(id, e.code, e.message);
  } catch (e) {
    return replyError(id, BridgeErrorCode.internal, e.toString());
  }
}

/// Scripts that emit typed events into the web view. Pass the result to runJavaScript.
abstract final class BridgeEvents {
  static String syncChanged({required List<String> buckets}) => eventScript('sync.changed', {'buckets': buckets});
  static String bundleUpdateReady({required int seq}) => eventScript('bundle.updateReady', {'seq': seq});
  static String appResumed() => eventScript('app.resumed', const <String, Object?>{});
  static String authExpired() => eventScript('auth.expired', const <String, Object?>{});
  static String syncDone({required SyncResult result}) => eventScript('sync.done', {'result': result.toJson()});
  static String appLifecycle({required String state}) => eventScript('app.lifecycle', {'state': state});
  static String appOnline({required bool online}) => eventScript('app.online', {'online': online});
  static String appAppearance({required bool darkMode, required bool highContrast, required bool reducedMotion}) => eventScript('app.appearance', {'darkMode': darkMode, 'highContrast': highContrast, 'reducedMotion': reducedMotion});
  static String linkOpened({required String url, required String path}) => eventScript('link.opened', {'url': url, 'path': path});
  static String permissionsChanged({required List<PermissionState> permissions}) => eventScript('permissions.changed', {'permissions': permissions.map((e) => e.toJson()).toList()});
  static String notifyTapped({required int id, required String? payload, required String? action}) => eventScript('notify.tapped', {'id': id, 'payload': payload, 'action': action});
  static String notifyAction({required int id, required String? payload, required String? action}) => eventScript('notify.action', {'id': id, 'payload': payload, 'action': action});
  static String pushReceived({required PushMessage message}) => eventScript('push.received', {'message': message.toJson()});
  static String pushTapped({required PushMessage message}) => eventScript('push.tapped', {'message': message.toJson()});
  static String pushTokenChanged({required String token}) => eventScript('push.tokenChanged', {'token': token});
}

/// Native plugin namespaces required by this app, including event-only fragments.
const hostPluginNamespaces = <String>{'haptics'};
/// Exact native method registrations required by the merged schema.
const hostPluginMethods = <String>{'haptics.tap'};

/// The built-in bridge methods, implemented against the `valence` runtime.
///
/// Extend it and implement your own methods; the built-ins are inherited. The bodies here are only
/// marshalling — every decision they make lives in the package, so a fix ships with an upgrade:
///
/// ```dart
/// class AppHandlers extends ValenceBuiltins implements BridgeHandlers {
///   AppHandlers(super.valence);
///
///   @override
///   Future<void> hapticsTap() async => HapticFeedback.lightImpact();
/// }
/// ```
abstract class ValenceBuiltins {
  /// Wraps an open runtime.
  ValenceBuiltins(this.valence, {List<ValencePlugin> plugins = const []})
      : plugins = ValencePluginRegistry.checked(plugins,
          requiredNamespaces: hostPluginNamespaces, requiredMethods: hostPluginMethods);

  /// Store-compiled native handlers. Dispatch still uses the generated strict decoders.
  final ValencePluginRegistry plugins;

  /// The runtime every built-in delegates to.
  final Valence valence;

  /// `app.ready`, from the package.
  Future<void> appReady() async {
    await valence.appReady();
  }

  /// `app.info`, from the package.
  Future<AppInfo> appInfo() async {
    final i = valence.appInfo();
    return AppInfo(platform: i.platform, host: i.host, bridge: i.bridge, bundle: i.bundle, locale: i.locale, fontScale: i.fontScale);
  }

  /// `data.get`, from the package.
  Future<Object?> dataGet(DataGetParams p) async {
    return valence.dataGet(p.bucket, p.key);
  }

  /// `data.list`, from the package.
  Future<List<Row>> dataList(DataListParams p) async {
    final rows = await valence.dataList(p.bucket, prefix: p.prefix, limit: p.limit, after: p.after);
    return [for (final r in rows) Row(key: r.key, value: r.value, usn: r.usn)];
  }

  /// `data.put`, from the package.
  Future<void> dataPut(DataPutParams p) async {
    await valence.dataPut(p.bucket, p.key, p.value);
  }

  /// `sync.now`, from the package.
  Future<SyncResult> syncNow(SyncNowParams p) async {
    final r = await valence.syncNow(buckets: p.buckets);
    return SyncResult(buckets: r.buckets, changed: r.changed, offline: r.offline, reason: r.reason.name, pending: r.pending);
  }

  /// `prefs.get`, from the package.
  Future<String?> prefsGet(PrefsGetParams p) async {
    return valence.prefsGet(p.key);
  }

  /// `prefs.set`, from the package.
  Future<void> prefsSet(PrefsSetParams p) async {
    await valence.prefsSet(p.key, p.value);
  }

  /// `open.external`, from the package.
  Future<void> openExternal(OpenExternalParams p) async {
    await plugins.invoke(valence, 'open.external', {'url': p.url});
  }

  /// `bundle.applyUpdate`, from the package.
  Future<void> bundleApplyUpdate() async {
    await valence.applyUpdate();
  }

  /// `secure.get`, from the package.
  Future<String?> secureGet(SecureGetParams p) async {
    return valence.secureGet(p.key);
  }

  /// `secure.set`, from the package.
  Future<void> secureSet(SecureSetParams p) async {
    await valence.secureSet(p.key, p.value);
  }

  /// `secure.delete`, from the package.
  Future<void> secureDelete(SecureDeleteParams p) async {
    await valence.secureDelete(p.key);
  }

  /// `auth.setToken`, from the package.
  Future<void> authSetToken(AuthSetTokenParams p) async {
    await valence.authSetToken(p.token, account: p.account, discardPending: p.discardPending ?? false);
  }

  /// `auth.hasToken`, from the package.
  Future<bool> authHasToken() async {
    return valence.authHasToken();
  }

  /// `auth.account`, from the package.
  Future<String?> authAccount() async {
    return valence.authAccount();
  }

  /// `http.request`, from the package.
  Future<HttpResponse> httpRequest(HttpRequestParams p) async {
    final r = await valence.httpRequest(url: p.url, method: p.method, headers: p.headers, body: p.body);
    return HttpResponse(status: r.status, headers: r.headers, body: r.body);
  }

  /// `data.getMany`, from the package.
  Future<List<Row>> dataGetMany(DataGetManyParams p) async {
    final rows = await valence.dataGetMany(p.bucket, p.keys);
    return [for (final r in rows) Row(key: r.key, value: r.value, usn: r.usn)];
  }

  /// `sync.status`, from the package.
  Future<SyncStatus> syncStatus() async {
    final r = await valence.syncStatus();
    return SyncStatus(pending: r.pending, lastSyncedAt: r.lastSyncedAt, offline: r.offline);
  }

  /// `app.state`, from the package.
  Future<AppState> appState() async {
    final s = valence.appState();
    return AppState(lifecycle: s.lifecycle.name, online: s.online);
  }

  /// `bundle.status`, from the package.
  Future<BundleStatus> bundleStatus() async {
    final s = valence.bundleStatus();
    return BundleStatus(serving: s.serving, pending: s.pending, trial: s.trial, reason: s.reason.name, offered: s.offered, checkedAt: s.checkedAt);
  }

  /// `data.count`, from the package.
  Future<int> dataCount(DataCountParams p) async {
    return valence.dataCount(p.bucket, prefix: p.prefix);
  }

  /// `state.save`, from the package.
  Future<void> stateSave(StateSaveParams p) async {
    valence.stateSave(p.json);
  }

  /// `state.restore`, from the package.
  Future<Object?> stateRestore() async {
    return valence.stateRestore();
  }

  /// `link.initial`, from the package.
  Future<Link?> linkInitial() async {
    final r = valence.linkInitial();
    return r == null ? null : Link(url: r.url, path: r.path);
  }

  /// `permissions.check`, from the package.
  Future<String> permissionsCheck(PermissionsCheckParams p) async {
    return valence.permissions.check(p.kind);
  }

  /// `permissions.request`, from the package.
  Future<String> permissionsRequest(PermissionsRequestParams p) async {
    return valence.permissions.request(p.kind);
  }

  /// `permissions.openSettings`, from the package.
  Future<bool> permissionsOpenSettings() async {
    return valence.permissions.openSettings();
  }

  /// `notify.permission`, from the package.
  Future<bool> notifyPermission(NotifyPermissionParams p) async {
    return valence.notifications.permission(request: p.request ?? false);
  }

  /// `notify.schedule`, from the package.
  Future<NotifyScheduled> notifySchedule(NotifyScheduleParams p) async {
    return NotifyScheduled.fromJson(await valence.notifications.schedule(id: p.id, title: p.title, body: p.body, at: p.at, channel: p.channel, exact: p.exact ?? false, payload: p.payload, image: p.image, actionIds: p.actions ?? const [], group: p.group));
  }

  /// `notify.cancel`, from the package.
  Future<void> notifyCancel(NotifyCancelParams p) async {
    await valence.notifications.cancel(p.id);
  }

  /// `notify.pending`, from the package.
  Future<List<NotifyPending>> notifyPending() async {
    return [for (final r in await valence.notifications.pending()) NotifyPending.fromJson(r)];
  }

  /// `notify.initial`, from the package.
  Future<Object?> notifyInitial() async {
    return valence.notifications.initial();
  }

  /// `notify.channels.set`, from the package.
  Future<void> notifyChannelsSet(NotifyChannelsSetParams p) async {
    await valence.notifications.channel(id: p.id, name: p.name, importance: p.importance ?? 'default', sound: p.sound, group: p.group, groupName: p.groupName);
  }

  /// `badge.set`, from the package.
  Future<bool> badgeSet(BadgeSetParams p) async {
    return valence.notifications.badge(p.n);
  }

  /// `badge.clear`, from the package.
  Future<bool> badgeClear() async {
    return valence.notifications.badge(0);
  }

  /// `push.token`, from the package.
  Future<String?> pushToken() async {
    return valence.pushToken();
  }

  /// `push.permission`, from the package.
  Future<String> pushPermission(PushPermissionParams p) async {
    return valence.pushPermission(request: p.request ?? false);
  }

  /// `push.initial`, from the package.
  Future<PushMessage?> pushInitial() async {
    final m = await valence.pushInitial();
    return m == null ? null : PushMessage(id: m.id, data: m.data, title: m.title, body: m.body, image: m.toJson()['image'] as String?);
  }

  /// `share.image`, from the package.
  Future<String> shareImage(ShareImageParams p) async {
    return valence.shareImage(bytes: p.bytes, path: p.path, fileName: p.fileName, caption: p.caption);
  }

  /// `haptics.tap`, from the package.
  Future<void> hapticsTap() async {
    await plugins.invoke(valence, 'haptics.tap', const <String, Object?>{});
  }
}
